#include <iostream>
#include <vector>
using namespace std;

int n;
vector<int> G[200005];
int L[200005], R[200005];
int leaf[200005];

int id = 0;
void dfs(int v, int p)
{
  if(v != 1 && G[v].size() == 1){
    leaf[v] = ++id;
    return;
  }
  for(auto u : G[v]) if(u != p) dfs(u, v);
}

void dfs2(int v, int p)
{
  if(leaf[v]){
    L[v] = R[v] = leaf[v];
    return;
  }
  L[v] = 1e9, R[v] = -1e9;
  for(auto u : G[v]){
    if(u == p) continue;
    dfs2(u, v);
    L[v] = min(L[v], L[u]);
    R[v] = max(R[v], R[u]);
  } 
}

int main(void)
{
  cin >> n;
  int u, v;
  for(int i = 1; i <= n-1; i++){
    cin >> u >> v;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  dfs(1, -1);
  dfs2(1, -1);
  for(int i = 1; i <= n; i++) cout << L[i] << " " << R[i] << "\n";

  return 0;
}
